/* b2-polish-snd.js — POLISH: звуки «Магната 2.0» (синтез POLISH-tools/snd.py → AAC, base64). Грузится по требованию (B2.need из POL.snd / первого касания).
   window.POLSND.play(name) → true, если сыграл. Громкость — общая; уважает S.sound и паузы shell (ac(), muted). Не править руками — пересобрать snd.py. */
(function(){'use strict';if(typeof window==='undefined')return;
var D={"tap": "", "coin": "", "coins": "", "cash": "", "stamp": "", "gavel": "", "bell": "", "pop": "", "swoosh": "", "win": "", "build": ""};
var BUF={},VOL={tap:.35,coin:.5,coins:.55,cash:.6,stamp:.7,gavel:.7,bell:.55,pop:.45,swoosh:.35,win:.55,build:.55},last={};
function A(){try{return typeof ac==='function'?ac():null;}catch(e){return null;}}
function dec(k){var a=A();if(!a||BUF[k])return;var s=atob(D[k]),u=new Uint8Array(s.length);for(var i=0;i<s.length;i++)u[i]=s.charCodeAt(i);BUF[k]=1;
  try{var p=a.decodeAudioData(u.buffer,function(b){BUF[k]=b;},function(){BUF[k]=0;});if(p&&p.catch)p.catch(function(){BUF[k]=0;});}catch(e){BUF[k]=0;}}
function play(k){if(!D[k])return false;try{if(typeof S!=='undefined'&&S&&S.sound===false)return true;if(typeof muted!=='undefined'&&muted)return true;}catch(e){}
  var a=A();if(!a)return false;var b=BUF[k];if(!b||b===1){dec(k);return false;}var n=performance.now();if(last[k]&&n-last[k]<60)return true;last[k]=n;
  try{var s=a.createBufferSource(),g=a.createGain();s.buffer=b;g.gain.value=VOL[k]||.5;s.connect(g).connect(a.destination);s.start(0);return true;}catch(e){return false;}}
function warm(){for(var k in D)dec(k);}
window.POLSND={play:play,warm:warm,list:Object.keys(D)};
// живые звуки вместо синтеза: coin, close (касса), gavel, win, build, tap; нет буфера — старый синтез
if(typeof SND!=='undefined'&&!SND.__pol){var O={};['tap','coin','close','gavel','win','build'].forEach(function(n){O[n]=SND[n];});SND.__pol=1;
  var M={tap:'tap',coin:'coin',close:'cash',gavel:'gavel',win:'win',build:'build'};
  Object.keys(M).forEach(function(n){SND[n]=function(){var r=play(M[n]);if(n==='tap'){try{if(typeof tapBuzz==='function')tapBuzz(6);}catch(e){}}if(!r&&O[n])return O[n].apply(this,arguments);};});}
warm();
})();
